import { chacha20poly1305 } from "@noble/ciphers/chacha.js"
import { x25519 } from "@noble/curves/ed25519.js"
import { hkdf } from "@noble/hashes/hkdf.js"
import { hmac } from "@noble/hashes/hmac.js"
import { sha256 } from "@noble/hashes/sha2.js"

export const NOISE_SUITE = "Noise_XX_25519_ChaChaPoly_SHA256"

export type NoiseRoute = { tenantId: string; routeId: string; hostId: string; deviceId: string }
export type NoiseKeyPair = { publicKey: Uint8Array; privateKey: Uint8Array }
export type NoiseFrame = { counter: number; keyEpoch: number; ciphertext: Uint8Array }

type HandshakeKeys = { send: Uint8Array; receive: Uint8Array; remoteStatic: Uint8Array }

/** Browser transport state for keys produced by the fixed Noise XX handshake. */
export class NoiseChannel {
  private sendCounter = 0
  private receiveCounter = 0
  private sendEpoch = 0
  private receiveEpoch = 0
  constructor(private sendKey: Uint8Array, private receiveKey: Uint8Array,
    private readonly route: NoiseRoute) {}

  encrypt(plaintext: Uint8Array): NoiseFrame {
    const counter = this.sendCounter++
    const ciphertext = chacha20poly1305(this.sendKey, nonce(counter),
      associatedData(this.route, "client", counter, this.sendEpoch)).encrypt(plaintext)
    return { counter, keyEpoch: this.sendEpoch, ciphertext }
  }

  decrypt(frame: NoiseFrame) {
    if (frame.counter !== this.receiveCounter || frame.keyEpoch !== this.receiveEpoch) {
      throw new Error("Noise frame replayed or out of order")
    }
    try {
      const plaintext = chacha20poly1305(this.receiveKey, nonce(frame.counter),
        associatedData(this.route, "host", frame.counter, frame.keyEpoch)).decrypt(frame.ciphertext)
      this.receiveCounter++
      return plaintext
    } catch (failure) {
      this.destroy()
      throw failure
    }
  }

  rekey() {
    this.sendKey = hmac(sha256, this.sendKey, new TextEncoder().encode("ji-noise-rekey"))
    this.receiveKey = hmac(sha256, this.receiveKey, new TextEncoder().encode("ji-noise-rekey"))
    this.sendEpoch++
    this.receiveEpoch++
    this.sendCounter = 0
    this.receiveCounter = 0
  }

  destroy() { this.sendKey.fill(0); this.receiveKey.fill(0) }
}

/** Derives a standards-compatible transport projection after XX has authenticated both static keys. */
export function transportFromHandshake(keys: HandshakeKeys, expectedHostKey: Uint8Array,
  chainingKey: Uint8Array, route: NoiseRoute) {
  if (!equal(keys.remoteStatic, expectedHostKey)) throw new Error("Host identity changed")
  const material = hkdf(sha256, concat(keys.send, keys.receive), chainingKey,
    new TextEncoder().encode(NOISE_SUITE), 64)
  return new NoiseChannel(material.slice(0, 32), material.slice(32), route)
}

export function generateNoiseKeyPair(): NoiseKeyPair {
  const privateKey = x25519.utils.randomSecretKey()
  return { privateKey, publicKey: x25519.getPublicKey(privateKey) }
}

function nonce(counter: number) {
  if (!Number.isSafeInteger(counter) || counter < 0) throw new Error("invalid Noise counter")
  const value = new Uint8Array(12)
  new DataView(value.buffer).setBigUint64(4, BigInt(counter), true)
  return value
}
function associatedData(route: NoiseRoute, direction: "client" | "host", counter: number, epoch: number) {
  return new TextEncoder().encode(`${route.routeId}\0${route.hostId}\0${route.deviceId}\0${direction}\0${counter}\0${epoch}`)
}
function concat(...values: Uint8Array[]) {
  const result = new Uint8Array(values.reduce((total, value) => total + value.length, 0))
  let offset = 0
  values.forEach(value => { result.set(value, offset); offset += value.length })
  return result
}
function equal(left: Uint8Array, right: Uint8Array) {
  return left.length === right.length && left.every((value, index) => value === right[index])
}
